/* The JX-8P factory patches (firmware/patches.c, generated by tools/jx8p.py). */
#include "../firmware/patches.h"
#include "../firmware/play.h"

static const patch *stab_brass(void)
{
    uint32_t n;
    for (n = 0; strcmp(PATCHES[n].name, "STAB BRASS") != 0; n++)
        ;
    return &PATCHES[n];
}

/* STAB BRASS's DCO-2 sounds osc 2 alone, open and dry, with its pitch envelope at `osc2` cents;
 * its pitch over 200..300 ms. */
static double stab_brass_osc2_hz(int32_t osc2)
{
    int32_t v[FM_PARAM_COUNT];
    uint32_t id;
    patch_values(stab_brass(), v);
    fm_engine_init(&mod_eng, MOD_RATE, 1);
    for (id = 0; id < FM_PARAM_COUNT; id++)
        fm_engine_set_param(&mod_eng, (uint16_t)id, v[id]);
    fm_engine_set_param(&mod_eng, FM_PARAM_OSC1_LEVEL, 0);
    fm_engine_set_param(&mod_eng, FM_PARAM_OSC2_LEVEL, 1000);
    fm_engine_set_param(&mod_eng, FM_PARAM_LFO_PITCH_CENTS, 0);
    fm_engine_set_param(&mod_eng, FM_PARAM_LFO_PITCH_OSC2_CENTS, 0);
    fm_engine_set_param(&mod_eng, FM_PARAM_CHORUS_MODE, 0);
    fm_engine_set_param(&mod_eng, FM_PARAM_FILTER_ENV_AMOUNT_CENTS, 0);
    fm_engine_set_param(&mod_eng, FM_PARAM_FILTER_CUTOFF_CENTS, FM_FILTER_OPEN_CENTS);
    fm_engine_set_param(&mod_eng, FM_PARAM_PITCH_ENV_OSC2_CENTS, osc2);
    fm_engine_note_on(&mod_eng, 57, 100);
    fm_engine_render(&mod_eng, mod_buf, MOD_RATE * 3 / 10);
    return hz_between(mod_buf, 200, 300);
}

/* Eric heard STAB BRASS out of tune: its DCO ENV names ENV-1 (51 ms attack, 42 ms decay to 27.6 %),
 * so PG-8X's DCO-2 settles at -384 x 0.276 = -106 cents within about 100 ms. With envelope 1 on
 * ENV-2's times (a 17.7 s decay) it sat near -384 instead. */
TT_TEST(stab_brass_osc2_settles_to_the_sustain_within_env1s_decay)
{
    int32_t depth = patch_value(stab_brass(), PATCH_PITCH_ENV_OSC2_CENTS);
    double c = cents(stab_brass_osc2_hz(depth), stab_brass_osc2_hz(0));
    printf("    STAB BRASS osc 2 at 200..300 ms: %.1f cents (depth %d)\n", c, (int)depth);
    TT_CHECK(fabs(c - depth * 0.276) < 12);
}

/* Every patch has a name, and the engine takes every value it has a param for as it is: in the
 * engine's range, so nothing is clamped. */
TT_TEST(patches_fit_the_engine)
{
    static fm_engine e;
    uint32_t n, f;
    for (n = 0; n < PATCH_COUNT; n++) {
        const patch *t = &PATCHES[n];
        TT_CHECK(t->name[0] != 0 && strlen(t->name) <= PATCH_NAME_MAX);
        TT_CHECK_EQ(fm_engine_init(&e, 44100, 4), FM_OK);
        for (f = 0; f < PATCH_FIELD_COUNT; f++) {
            int32_t id = patch_param((patch_field)f), v;
            if (id == PATCH_NONE)
                continue;
            v = patch_value(t, (patch_field)f);
            TT_CHECK_EQ(fm_engine_set_param(&e, (uint16_t)id, v), FM_OK);
            TT_CHECK_EQ(fm_engine_get_param(&e, (uint16_t)id), v);
        }
    }
}

/* The fields the engine has no param for yet wait for their features (patches.h). */
TT_TEST(patches_keep_the_fields_the_engine_lacks)
{
    TT_CHECK_EQ(patch_param(PATCH_OSC1_WAVE), FM_PARAM_OSC1_WAVE);
    TT_CHECK_EQ(patch_param(PATCH_FILTER_CUTOFF_CENTS), FM_PARAM_FILTER_CUTOFF_CENTS);
    TT_CHECK_EQ(patch_param(PATCH_PITCH_ENV_OSC1_CENTS), FM_PARAM_PITCH_ENV_OSC1_CENTS);
    TT_CHECK_EQ(patch_param(PATCH_FILTER_LFO_PERMILLE), PATCH_NONE);
    TT_CHECK_EQ(patch_param(PATCH_AMP_GATE), PATCH_NONE);
    TT_CHECK_EQ(patch_param(PATCH_FIELD_COUNT), PATCH_NONE);
    TT_CHECK_EQ(patch_value(&PATCHES[PATCH_SOUNDTRACK], PATCH_FILTER_ENV_SOURCE), 0);   /* ENV-1 */
}

/* Soundtrack as every param's value, and what the playable module boots with, checked against values
 * known apart from patch_values: tone 17 of the factory dump decoded by hand (docs/patches.md; two
 * saws an octave down, DCO-2 a little flat, a dark unresonant low pass, no HPF) and the engine's
 * documented defaults (fm1_8p.h) for the params no field sets. */
TT_TEST(patch_values_are_the_boot_state)
{
    static play pl;
    int32_t v[FM_PARAM_COUNT];
    uint32_t i;
    patch_values(&PATCHES[PATCH_SOUNDTRACK], v);
    TT_CHECK_EQ(v[FM_PARAM_OSC1_WAVE], FM_WAVE_SAW);
    TT_CHECK_EQ(v[FM_PARAM_OSC2_WAVE], FM_WAVE_SAW);
    TT_CHECK_EQ(v[FM_PARAM_OSC1_OCTAVE], -1);
    TT_CHECK_EQ(v[FM_PARAM_OSC2_OCTAVE], -1);
    TT_CHECK_EQ(v[FM_PARAM_OSC2_FINE_CENTS], -13);
    TT_CHECK_EQ(v[FM_PARAM_FILTER_CUTOFF_CENTS], 6400);
    TT_CHECK_EQ(v[FM_PARAM_FILTER_RESONANCE], 0);
    TT_CHECK_EQ(v[FM_PARAM_HIGHPASS_STEP], 0);
    TT_CHECK_EQ(v[FM_PARAM_BEND_RANGE], 2);             /* no field: the defaults */
    TT_CHECK_EQ(v[FM_PARAM_VOICE_MODE], FM_VOICE_MODE_POLY);
    TT_CHECK_EQ(v[FM_PARAM_UNISON_DETUNE_CENTS], 20);
    TT_CHECK_EQ(play_init(&pl), 0);
    for (i = 0; i < FM_PARAM_COUNT; i++)
        TT_CHECK_EQ(fm_engine_get_param(&pl.engine, (uint16_t)i), v[i]);
}

/* A param no field sets (bend range, voice mode, ...) takes the table's default, whatever the patch. */
TT_TEST(patch_values_default_what_no_field_sets)
{
    int32_t v[FM_PARAM_COUNT];
    uint32_t n, i, f, set[FM_PARAM_COUNT] = {0};
    for (f = 0; f < PATCH_FIELD_COUNT; f++)
        if (patch_param((patch_field)f) != PATCH_NONE)
            set[patch_param((patch_field)f)] = 1;
    TT_CHECK(!set[FM_PARAM_BEND_RANGE]);                /* so the loop below checks something */
    for (n = 0; n < PATCH_COUNT; n++) {
        patch_values(&PATCHES[n], v);
        for (i = 0; i < FM_PARAM_COUNT; i++)
            if (!set[i])
                TT_CHECK_EQ(v[i], fm_param_info_get((uint16_t)i)->def);
    }
}

/* A field outside its param's range is clamped to it, so a patch never sets a value the engine
 * would refuse (the factory ones all fit: patches_fit_the_engine). */
TT_TEST(patch_values_clamp_to_the_param_range)
{
    const fm_param_info *cut = fm_param_info_get(FM_PARAM_FILTER_CUTOFF_CENTS);
    const fm_param_info *res = fm_param_info_get(FM_PARAM_FILTER_RESONANCE);
    patch t = PATCHES[0];
    int32_t v[FM_PARAM_COUNT];
    t.v[PATCH_FILTER_CUTOFF_CENTS] = (uint16_t)(cut->max + 1 + PATCH_BIAS);
    t.v[PATCH_FILTER_RESONANCE_PERMILLE] = (uint16_t)(res->min - 1 + PATCH_BIAS);
    patch_values(&t, v);
    TT_CHECK_EQ(v[FM_PARAM_FILTER_CUTOFF_CENTS], cut->max);
    TT_CHECK_EQ(v[FM_PARAM_FILTER_RESONANCE], res->min);
}

static void run_patches_tests(void)
{
    TT_RUN(patches_fit_the_engine);
    TT_RUN(patches_keep_the_fields_the_engine_lacks);
    TT_RUN(patch_values_are_the_boot_state);
    TT_RUN(patch_values_default_what_no_field_sets);
    TT_RUN(patch_values_clamp_to_the_param_range);
    TT_RUN(stab_brass_osc2_settles_to_the_sustain_within_env1s_decay);
}
